artist_names = {}
for artist_id in artist_ids_needed:
    response = apis.spotify.show_artist(artist_id=artist_id)
    if isinstance(response, dict) and 'message' in response:
        print(f"Error fetching artist {artist_id}: {response}")
        continue
    artist_names[artist_id] = response['name']

print(f"Fetched {len(artist_names)} artist names")
# Print a few for verification
for aid, name in list(artist_names.items())[:5]:
    print(aid, name)

